-- French curriculum (PLAN-multilingua.md, PR 8): 24 chapters A1-B2 x 4 lessons, same structure as the English one.
-- Titles and descriptions in Italian (the native language); grammar_focus and focus in English, for the prompts.
-- Written once and reviewed; the lessons themselves are generated (and shared) by the `lesson` function.

insert into public.chapters (language, level, sort_order, slug, title, description_it, grammar_focus) values
  ('fr', 'A1', 1, 'a1-etre', 'Presentarsi', 'Il verbo être, i saluti, le nazionalità, i numeri e la famiglia.', 'verb être (present) affirmative, negative and questions; subject pronouns; tu vs vous; greetings; countries and nationalities; numbers; possessive adjectives'),
  ('fr', 'A1', 2, 'a1-articles', 'Le cose intorno a me', 'Articoli, genere, plurali e il y a.', 'definite and indefinite articles (le/la/l''/les, un/une/des); gender of nouns; plurals in -s and -x; il y a; prepositions of place'),
  ('fr', 'A1', 3, 'a1-present-er', 'La mia giornata', 'Il presente dei verbi in -er e i verbi riflessivi.', 'present tense of -er verbs; reflexive verbs for the daily routine; telling the time; days of the week; adverbs of frequency'),
  ('fr', 'A1', 4, 'a1-questions', 'Domande e negazioni', 'Fare domande e rispondere, dire cosa piace.', 'questions with est-ce que and intonation; question words; negation ne...pas / ne...jamais / ne...rien; aimer/adorer/détester + noun or infinitive'),
  ('fr', 'A1', 5, 'a1-irreguliers', 'Andare, fare, potere', 'I verbi irregolari più comuni, l''imperativo e le indicazioni.', 'irregular present of aller, faire, pouvoir, vouloir, prendre; à + article (au, aux); imperative; asking for and giving directions'),
  ('fr', 'A1', 6, 'a1-maintenant', 'Adesso e tra poco', 'Cosa sto facendo, cosa farò tra poco, il tempo e i vestiti.', 'être en train de + infinitive; futur proche (aller + infinitive); weather expressions; clothes; adjective agreement and colours'),
  ('fr', 'A2', 1, 'a2-passe-compose', 'Ieri', 'Il passé composé con avoir e le espressioni di tempo.', 'passé composé with avoir; regular and common irregular past participles; negative and questions in the passé composé; past time expressions (hier, la semaine dernière, il y a)'),
  ('fr', 'A2', 2, 'a2-passe-etre', 'Raccontare il passato', 'Il passé composé con être e i verbi riflessivi.', 'passé composé with être (verbs of movement and change of state); agreement of the past participle with être; reflexive verbs in the passé composé; sequencing words'),
  ('fr', 'A2', 3, 'a2-partitif', 'Cibo e quantità', 'Il partitivo, le quantità, il pronome en e ordinare.', 'partitive articles du/de la/de l''/des; de after negation and quantities; beaucoup de, un peu de, un kilo de; pronoun en; je voudrais; ordering food'),
  ('fr', 'A2', 4, 'a2-comparatif', 'Fare confronti', 'Comparativi, superlativi e la posizione degli aggettivi.', 'comparatives plus/moins/aussi ... que; superlatives le plus / le moins; bon/meilleur, bien/mieux; position and agreement of adjectives (grand, petit, beau, nouveau, vieux)'),
  ('fr', 'A2', 5, 'a2-imparfait', 'Com''era una volta', 'L''imparfait per descrivere e per le abitudini nel passato.', 'imparfait formation; imparfait for descriptions and habits in the past; imparfait vs passé composé'),
  ('fr', 'A2', 6, 'a2-pronoms', 'I pronomi', 'Pronomi diretti e indiretti, y e la loro posizione.', 'direct object pronouns le/la/l''/les; indirect object pronouns lui/leur; me/te/nous/vous; pronoun y; position of pronouns with the infinitive and the passé composé'),
  ('fr', 'B1', 1, 'b1-futur', 'Il futuro', 'Il futuro semplice, quand + futuro e si + presente.', 'futur simple of regular and irregular verbs; quand + futur; si + présent, futur; future time expressions'),
  ('fr', 'B1', 2, 'b1-conditionnel', 'Se fossi...', 'Il condizionale presente: ipotesi, cortesia e consigli.', 'conditionnel présent formation; si + imparfait, conditionnel; politeness (je voudrais, pourriez-vous); advice (tu devrais, à ta place)'),
  ('fr', 'B1', 3, 'b1-subjonctif', 'Bisogna che...', 'Il congiuntivo presente dopo verbi di necessità, volontà ed emozione.', 'subjonctif présent formation (regular and être, avoir, aller, faire, pouvoir); after il faut que, vouloir que, emotions; subjonctif vs indicatif after penser/croire'),
  ('fr', 'B1', 4, 'b1-relatifs', 'Frasi relative', 'I pronomi relativi qui, que, où, dont e ce qui / ce que.', 'relative pronouns qui, que, où, dont; ce qui / ce que; agreement in relative clauses'),
  ('fr', 'B1', 5, 'b1-recit', 'Raccontare una storia', 'Il trapassato prossimo e le espressioni di tempo nei racconti.', 'plus-que-parfait; narrative tenses together (passé composé, imparfait, plus-que-parfait); depuis / pendant / il y a; venir de + infinitive'),
  ('fr', 'B1', 6, 'b1-discours', 'Il discorso indiretto', 'Riferire affermazioni, domande e ordini.', 'reported speech in the present and in the past; concordance des temps; indirect questions with si, ce que, ce qui; reported commands with de + infinitive'),
  ('fr', 'B2', 1, 'b2-conditionnel-passe', 'Rimpianti e ipotesi', 'Il condizionale passato e le ipotesi nel passato.', 'conditionnel passé; si + plus-que-parfait, conditionnel passé; mixed hypotheses; regrets and reproaches (j''aurais dû, tu aurais pu)'),
  ('fr', 'B2', 2, 'b2-subjonctif', 'Il congiuntivo avanzato', 'Il congiuntivo dopo le congiunzioni e il congiuntivo passato.', 'subjonctif after conjunctions (bien que, pour que, avant que, à moins que, jusqu''à ce que, sans que); subjonctif passé; subjonctif in relative clauses'),
  ('fr', 'B2', 3, 'b2-passif', 'La forma passiva', 'Il passivo, se faire + infinito e i modi di evitarlo.', 'passive voice in different tenses; par vs de; se faire + infinitive; on and the pronominal passive (ça se dit, ça se mange)'),
  ('fr', 'B2', 4, 'b2-participe', 'Gerundio e participio', 'Il gérondif, il participio presente e l''accordo del participio passato.', 'gérondif (en + -ant) for simultaneity, manner and condition; participe présent; agreement of the past participle with avoir (preceding direct object)'),
  ('fr', 'B2', 5, 'b2-pronoms', 'Pronomi doppi e relativi composti', 'I pronomi doppi, lequel e i dimostrativi.', 'double object pronouns and their order; y and en together; lequel/auquel/duquel; demonstrative pronouns celui/celle/ceux'),
  ('fr', 'B2', 6, 'b2-connecteurs', 'Collegare le idee', 'Connettivi per argomentare e scrivere testi chiari.', 'linking words for cause (parce que, puisque, car, comme), consequence (donc, c''est pourquoi, si bien que), opposition and concession (pourtant, cependant, alors que, même si); expressing an opinion');

